-- Cavite PDRRMO evacuation centers and historical records (revision 3, generated 2026-10-24)
-- Safe to run more than once: every insert is skipped when the row already exists.
SET NAMES utf8mb4;
-- Revision-3 columns (the app also adds these by itself on first use; IF NOT EXISTS needs MariaDB).
ALTER TABLE historical_disasters ADD COLUMN IF NOT EXISTS event_name VARCHAR(160) NULL AFTER disaster_type, ADD COLUMN IF NOT EXISTS injured INT UNSIGNED NOT NULL DEFAULT 0 AFTER casualties, ADD COLUMN IF NOT EXISTS evacuated_families INT UNSIGNED NOT NULL DEFAULT 0 AFTER injured, ADD COLUMN IF NOT EXISTS affected_barangays TEXT NULL AFTER evacuated_families, ADD COLUMN IF NOT EXISTS affected_barangay_count INT UNSIGNED NOT NULL DEFAULT 0 AFTER affected_barangays, ADD COLUMN IF NOT EXISTS source VARCHAR(255) NULL AFTER damages;
